import { prisma } from "@/lib/prisma";
import { requireAdmin } from "@/lib/admin-api";

export const runtime = "nodejs";

// GET /api/admin/company-earnings — referral commission the program RETAINED, i.e.
// commission generated by referrers who had not yet reached their milestone.
//
// Worth being precise about what this is: it is NOT a pot of money that was moved
// anywhere. Every customer payment already lands in the company's Razorpay account;
// retaining commission just means never crediting it out. So this is a ledger of
// revenue NOT given away — read it as "referral payouts avoided", and reconcile it
// against Razorpay settlements, not against a separate balance.
export async function GET(request) {
  const { error } = await requireAdmin();
  if (error) return error;

  const { searchParams } = new URL(request.url);
  const take = Math.min(Number(searchParams.get("limit")) || 100, 500);

  const [total, count, earnings, topReferrers] = await Promise.all([
    prisma.companyEarning.aggregate({ _sum: { amount: true } }),
    prisma.companyEarning.count(),
    prisma.companyEarning.findMany({
      orderBy: { createdAt: "desc" },
      take,
      include: {
        referrer: { select: { id: true, name: true, email: true, referralMilestoneAt: true } },
      },
    }),
    // Who is generating the most retained commission — these are the customers
    // closest to (or newly past) their milestone.
    prisma.companyEarning.groupBy({
      by: ["referrerId"],
      _sum: { amount: true },
      _count: { _all: true },
      orderBy: { _sum: { amount: "desc" } },
      take: 10,
    }),
  ]);

  const referrerIds = topReferrers.map((r) => r.referrerId).filter(Boolean);
  const referrers = await prisma.user.findMany({
    where: { id: { in: referrerIds } },
    select: { id: true, name: true, email: true, referralMilestoneAt: true },
  });
  const byId = new Map(referrers.map((r) => [r.id, r]));

  return Response.json({
    totalRetained: Number(total._sum.amount || 0),
    count,
    earnings,
    topReferrers: topReferrers.map((r) => ({
      referrer: byId.get(r.referrerId) || null,
      total: Number(r._sum.amount || 0),
      orders: r._count._all,
    })),
  });
}
